 for(const feat of feats.filter(f=>f.startsWith('Magic Initiate'))){const cl=feat.match(/\(([^)]+)\)/)[1],m=d.magic?.[cl]??{cantrips:[],spell:'',ability:'wis'};validSpells(m.cantrips??[],2,cl,0,feat);validSpells(m.spell?[m.spell]:[],1,cl,1,feat);for(const s of spells.filter(s=>s.source===feat)){s.ability=m.ability;s.free_casts=s.level===1?1:0;}if(!['int','wis','cha'].includes(m.ability))errors.push('Choose a Magic Initiate casting ability.');}
 const speciesCantrips={Elf:{Drow:['Dancing Lights'],'High Elf':d.lineageCantrip?[d.lineageCantrip]:[], 'Wood Elf':['Druidcraft']},Gnome:{'Forest Gnome':['Minor Illusion'],'Rock Gnome':['Mending','Prestidigitation']},Tiefling:{Abyssal:['Thaumaturgy','Poison Spray'],Chthonic:['Thaumaturgy','Chill Touch'],Infernal:['Thaumaturgy','Fire Bolt']}};
